ee:message.ee:set-payload:
%dw 2.0
output application/json  skipNullOn = "everywhere"
---
{
	"recipientData": payload.recipients map ((recipient, index) -> {
		"recipient": {
			"customerId": recipient.customerId,
			"mobileNumber": recipient.mobileNumber,
			"emailAddress": recipient.emailAddress,
			"emailMD5Hash": recipient.emailMD5Hash,
			"emailSHA256Hash": recipient.emailSHA256Hash,
			"recipientId": recipient.recipientId,
			"emailFormat": recipient.emailFormat,
			"listName": {
				"folderName": recipient.listFolderName,
				"objectName": recipient.listObjectName
			}
		},
		"optionalData": recipient.optionalData map {
			name: $.name,
			value: $.value
		}
	})
}

%dw 2.0
output application/json
---
if ( error.description contains "NO_RECIPIENT_FOUND" ) {
	"status": "404",
	"code": "RESPONSYS:NO_RECIPIENT_FOUND",
	"message": error.description,
	"messageServer": error.description,
	"cause": [{
		"origin": "oracle-sapi-services",
		"message": error.description
	}]
}
else if ( error.description contains "INVALID_MOBILE_NUMBER_FORMAT" ) {
	"status": "400",
	"code": "RESPONSYS:INVALID_MOBILE_NUMBER_FORMAT",
	"message": error.description,
	"messageServer": error.description,
	"cause": [{
		"origin": "oracle-sapi-services",
		"message": error.description
	}]
}
else
{
	"status": "500",
	"code": "RESPONSYS:NOTIFICATION_ERROR",
	"message": error.description,
	"messageServer": error.description,
	"cause": [{
		"origin": "oracle-sapi-services",
		"message": error.description
	}]
}
